-- PostgreSQL: review and apply once before enabling VNPAY on an existing database.
-- This module has no migration runner; this script is not executed automatically.
BEGIN;
ALTER TABLE payments ADD COLUMN IF NOT EXISTS vnpay_transaction_no VARCHAR(15);
CREATE UNIQUE INDEX IF NOT EXISTS uk_payments_vnpay_transaction_no
    ON payments (vnpay_transaction_no);

-- Default PostgreSQL check names generated by the existing Hibernate enum mapping.
-- If your schema uses custom names, replace the corresponding constraints instead.
ALTER TABLE payments DROP CONSTRAINT IF EXISTS payments_method_check;
ALTER TABLE payments ADD CONSTRAINT payments_method_check
    CHECK (method IN ('COD', 'BANK_TRANSFER', 'VNPAY'));
ALTER TABLE orders DROP CONSTRAINT IF EXISTS orders_payment_method_check;
ALTER TABLE orders ADD CONSTRAINT orders_payment_method_check
    CHECK (payment_method IN ('COD', 'BANK_TRANSFER', 'VNPAY'));
COMMIT;
